class Operations:
    """Every public operation of agents-service, by its operationId."""

    def __init__(self, transport: Transport) -> None:
        self._t = transport

    def health_health(self) -> HealthStatus:
        "Health"
        return self._t.call(SERVICE, OPERATIONS["health_health"], {}, {}, {}, None)  # type: ignore[no-any-return]

    def background_health_background(self) -> BackgroundHealthOut:
        "Health Background"
        return self._t.call(SERVICE, OPERATIONS["background_health_background"], {}, {}, {}, None)  # type: ignore[no-any-return]

    def reviews_list_reviews(
        self,
        *,
        view: str | None = None,
        page: int | None = None,
        page_size: int | None = None,
        search: str | None = None,
        risk: list[str] | None = None,
        workflow_id: list[str] | None = None,
        kind: list[str] | None = None,
        agent_slug: list[str] | None = None,
        status: list[str] | None = None,
        group: str | None = None,
    ) -> ReviewList:
        "List Reviews"
        return self._t.call(
            SERVICE,
            OPERATIONS["reviews_list_reviews"],
            {},
            {
                "view": view,
                "page": page,
                "pageSize": page_size,
                "search": search,
                "risk": risk,
                "workflowId": workflow_id,
                "kind": kind,
                "agentSlug": agent_slug,
                "status": status,
                "group": group,
            },
            {},
            None,
        )  # type: ignore[no-any-return]

    def reviews_assign(self, body: AssignInput) -> BulkResult:
        "Assign"
        return self._t.call(SERVICE, OPERATIONS["reviews_assign"], {}, {}, {}, body)  # type: ignore[no-any-return]

    def reviews_bulk_decide(self, body: BulkDecisionInput) -> BulkResult:
        "Bulk Decide"
        return self._t.call(SERVICE, OPERATIONS["reviews_bulk_decide"], {}, {}, {}, body)  # type: ignore[no-any-return]

    def reviews_get_review_by_run_key(self, run_key: str) -> Any:
        "Get Review By Run Key"
        return self._t.call(SERVICE, OPERATIONS["reviews_get_review_by_run_key"], {"run_key": run_key}, {}, {}, None)  # type: ignore[no-any-return]

    def reviews_get_queue_place(
        self, review_id: str, *, view: str | None = None, group: str | None = None
    ) -> QueuePlace:
        "Get Queue Place"
        return self._t.call(
            SERVICE,
            OPERATIONS["reviews_get_queue_place"],
            {"review_id": review_id},
            {"view": view, "group": group},
            {},
            None,
        )  # type: ignore[no-any-return]

    def reviews_get_review(self, thread_id: str) -> Any:
        "Get Review"
        return self._t.call(SERVICE, OPERATIONS["reviews_get_review"], {"thread_id": thread_id}, {}, {}, None)  # type: ignore[no-any-return]

